import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const dbPath = process.env.DB_PATH || join(root, 'data', 'workboard.sqlite');
mkdirSync(dirname(dbPath), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL
)`);
if (!db.prepare('PRAGMA table_info(projects)').all().some(column => column.name === 'archived')) {
  db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}
const insertProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id),
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
);
CREATE INDEX IF NOT EXISTS tasks_project ON tasks(project_id, id)`);
const projectQuery = `SELECT p.id, p.name, p.archived,
  (SELECT COUNT(*) FROM tasks WHERE project_id = p.id) AS total_count,
  (SELECT COUNT(*) FROM tasks WHERE project_id = p.id AND completed = 1) AS completed_count
  FROM projects p`;
const listProjects = db.prepare(`${projectQuery} ORDER BY p.id`);
const getProject = db.prepare(`${projectQuery} WHERE p.id = ?`);
const updateProject = db.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const projectValue = project => ({ ...project, archived: Boolean(project.archived) });
const listTasks = db.prepare('SELECT id, project_id, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const getTask = db.prepare('SELECT id, project_id, title, completed FROM tasks WHERE project_id = ? AND id = ?');
const insertTask = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE project_id = ? AND id = ?');
const taskValue = task => ({ ...task, completed: Boolean(task.completed) });
const assets = new Map([
  ['/', ['text/html; charset=utf-8', readFileSync(join(root, 'public', 'index.html'))]],
  ['/app.js', ['text/javascript; charset=utf-8', readFileSync(join(root, 'public', 'app.js'))]],
  ['/style.css', ['text/css; charset=utf-8', readFileSync(join(root, 'public', 'style.css'))]],
]);

function json(res, status, value) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(value));
}

async function readInput(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (Buffer.byteLength(body) > 65536) {
      throw Object.assign(new Error('Request is too large'), { status: 413 });
    }
  }
  try {
    return JSON.parse(body);
  } catch {
    throw Object.assign(new Error('Invalid JSON'), { status: 400 });
  }
}

const server = http.createServer(async (req, res) => {
  try {
    const path = new URL(req.url, 'http://localhost').pathname;
    if (req.method === 'GET' && path === '/health') {
      return json(res, 200, { status: 'ok' });
    }
    if (req.method === 'GET' && path === '/api/projects') {
      return json(res, 200, listProjects.all().map(projectValue));
    }
    const projectMatch = path.match(/^\/api\/projects\/(\d+)$/);
    if (req.method === 'GET' && projectMatch) {
      const project = getProject.get(projectMatch[1]);
      return json(res, project ? 200 : 404, project ? projectValue(project) : { error: 'Project not found' });
    }
    if (req.method === 'PATCH' && projectMatch) {
      if (!getProject.get(projectMatch[1])) return json(res, 404, { error: 'Project not found' });
      const input = await readInput(req);
      if (typeof input?.archived !== 'boolean') {
        return json(res, 400, { error: 'Archive state must be true or false' });
      }
      updateProject.run(Number(input.archived), projectMatch[1]);
      return json(res, 200, projectValue(getProject.get(projectMatch[1])));
    }
    if (req.method === 'POST' && path === '/api/projects') {
      const input = await readInput(req);
      const name = typeof input?.name === 'string' ? input.name.trim() : '';
      if (!name) return json(res, 400, { error: 'Project name is required' });
      const result = insertProject.run(name);
      return json(res, 201, projectValue(getProject.get(result.lastInsertRowid)));
    }
    const tasksMatch = path.match(/^\/api\/projects\/(\d+)\/tasks(?:\/(\d+))?$/);
    if (tasksMatch) {
      const [, projectId, taskId] = tasksMatch;
      if (!getProject.get(projectId)) return json(res, 404, { error: 'Project not found' });
      if (req.method === 'GET' && !taskId) {
        return json(res, 200, listTasks.all(projectId).map(taskValue));
      }
      if (req.method === 'POST' && !taskId) {
        const input = await readInput(req);
        if (getProject.get(projectId).archived) return json(res, 409, { error: 'Archived project' });
        const title = typeof input?.title === 'string' ? input.title.trim() : '';
        if (!title) return json(res, 400, { error: 'Task title is required' });
        const result = insertTask.run(projectId, title);
        return json(res, 201, taskValue(getTask.get(projectId, result.lastInsertRowid)));
      }
      if (req.method === 'PATCH' && taskId) {
        if (!getTask.get(projectId, taskId)) return json(res, 404, { error: 'Task not found' });
        const input = await readInput(req);
        if (getProject.get(projectId).archived) return json(res, 409, { error: 'Archived project' });
        if (typeof input?.completed !== 'boolean') {
          return json(res, 400, { error: 'Completion must be true or false' });
        }
        updateTask.run(Number(input.completed), projectId, taskId);
        return json(res, 200, taskValue(getTask.get(projectId, taskId)));
      }
    }
    if (req.method === 'GET') {
      const asset = assets.get(/^\/projects\/\d+$/.test(path) ? '/' : path);
      if (asset) {
        res.writeHead(200, { 'Content-Type': asset[0] });
        return res.end(asset[1]);
      }
    }
    json(res, 404, { error: 'Not found' });
  } catch (error) {
    if (error.status) return json(res, error.status, { error: error.message });
    console.error(error);
    if (!res.headersSent) json(res, 500, { error: 'Unable to complete request' });
    else res.end();
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
function shutdown() {
  server.close(() => {
    db.close();
    process.exit(0);
  });
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);
const app = document.querySelector('#app');

async function request(path, options) {
  const response = await fetch(path, options);
  const result = await response.json();
  if (!response.ok) throw new Error(result.error || 'Unable to complete request');
  return result;
}

function alertMessage(message) {
  const alert = app.querySelector('[role="alert"]');
  alert.textContent = message;
  alert.hidden = !message;
}

function navigate(path) {
  history.pushState(null, '', path);
  render();
}

function projectRow(project, onUpdate) {
  const row = document.createElement('li');
  row.dataset.testid = 'project-row';
  const name = document.createElement('span');
  name.textContent = project.name;
  const button = document.createElement('button');
  button.textContent = 'Open project';
  button.addEventListener('click', () => navigate(`/projects/${project.id}`));
  const summary = document.createElement('span');
  summary.dataset.testid = 'project-summary';
  summary.textContent = `${project.completed_count}/${project.total_count} completed`;
  const archive = document.createElement('button');
  archive.textContent = project.archived ? 'Restore project' : 'Archive project';
  archive.addEventListener('click', async () => {
    archive.disabled = true;
    alertMessage('');
    try {
      const saved = await request(`/api/projects/${project.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ archived: !project.archived }),
      });
      onUpdate(saved);
    } catch (error) {
      if (row.isConnected) alertMessage(error.message);
    } finally {
      archive.disabled = false;
    }
  });
  row.append(name, summary, button, archive);
  return row;
}

async function render() {
  const path = location.pathname;
  app.setAttribute('aria-busy', 'true');
  const match = path.match(/^\/projects\/(\d+)$/);
  if (match) {
    app.innerHTML = `<button id="projects">Projects</button><h1></h1>
      <p id="archive-status" hidden>Archived project</p>
      <form>
        <label for="task-title">Task title</label>
        <div class="create-controls">
          <input id="task-title" type="text" autocomplete="off">
          <button type="submit" disabled>Create task</button>
        </div>
      </form>
      <p role="alert" hidden></p>
      <div class="task-filter">
        <label for="task-filter">Task filter</label>
        <select id="task-filter">
          <option>All</option><option>Open</option><option>Completed</option>
        </select>
      </div>
      <ul id="task-list" aria-label="Tasks"></ul>`;
    app.querySelector('#projects').addEventListener('click', () => navigate('/'));
    const form = app.querySelector('form');
    const input = app.querySelector('input');
    const submit = form.querySelector('button');
    const filter = app.querySelector('select');
    const list = app.querySelector('ul');
    const endpoint = `/api/projects/${match[1]}/tasks`;
    let tasks = [];
    let archived = false;
    function displayTasks() {
      const visible = tasks.filter(task => filter.value === 'All' ||
        (filter.value === 'Completed' ? task.completed : !task.completed));
      list.replaceChildren(...visible.map(task => {
        const row = document.createElement('li');
        row.dataset.testid = 'task-row';
        const title = document.createElement('span');
        title.textContent = task.title;
        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.checked = task.completed;
        checkbox.disabled = archived;
        checkbox.setAttribute('aria-label', `Complete ${task.title}`);
        checkbox.addEventListener('change', async () => {
          checkbox.disabled = true;
          alertMessage('');
          try {
            const saved = await request(`${endpoint}/${task.id}`, {
              method: 'PATCH',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ completed: checkbox.checked }),
            });
            tasks = tasks.map(item => item.id === saved.id ? saved : item);
            if (list.isConnected) displayTasks();
          } catch (error) {
            checkbox.checked = task.completed;
            if (list.isConnected) alertMessage(error.message);
          } finally {
            checkbox.disabled = archived;
          }
        });
        row.append(title, checkbox);
        return row;
      }));
    }
    filter.addEventListener('change', displayTasks);
    form.addEventListener('submit', async event => {
      event.preventDefault();
      if (submit.disabled) return;
      const title = input.value.trim();
      if (!title) {
        alertMessage('Task title is required');
        input.focus();
        return;
      }
      submit.disabled = true;
      alertMessage('');
      try {
        const task = await request(endpoint, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ title }),
        });
        tasks.push(task);
        if (!form.isConnected) return;
        displayTasks();
        input.value = '';
        input.focus();
      } catch (error) {
        if (form.isConnected) alertMessage(error.message);
      } finally {
        submit.disabled = archived;
      }
    });
    try {
      const project = await request(`/api/projects/${match[1]}`);
      if (!form.isConnected) return;
      app.querySelector('h1').textContent = project.name;
      archived = project.archived;
      app.querySelector('#archive-status').hidden = !archived;
      document.title = `${project.name} · Workboard`;
      tasks = await request(endpoint);
      if (!list.isConnected) return;
      displayTasks();
      submit.disabled = archived;
    } catch (error) {
      if (location.pathname === path) alertMessage(error.message);
    }
  } else {
    document.title = 'Workboard';
    app.innerHTML = `
      <h1>Workboard</h1>
      <form>
        <label for="project-name">Project name</label>
        <div class="create-controls">
          <input id="project-name" name="name" type="text" autocomplete="off">
          <button type="submit">Create project</button>
        </div>
      </form>
      <p role="alert" hidden></p>
      <div class="project-filter">
        <label for="project-filter">Project filter</label>
        <select id="project-filter"><option>Active</option><option>Archived</option></select>
      </div>
      <ul id="project-list" aria-label="Projects"></ul>`;
    const form = app.querySelector('form');
    const input = app.querySelector('input');
    const list = app.querySelector('ul');
    const submit = form.querySelector('button');
    const filter = app.querySelector('select');
    let projects = [];
    // A fresh browser session starts with Active; reloads and Projects navigation
    // keep the user's current view, including while opening archived projects.
    try {
      if (sessionStorage.getItem('project-filter') === 'Archived') filter.value = 'Archived';
    } catch { /* The list still works when browser storage is unavailable. */ }
    function displayProjects() {
      list.replaceChildren(...projects
        .filter(project => project.archived === (filter.value === 'Archived'))
        .map(project => projectRow(project, saved => {
          projects = projects.map(item => item.id === saved.id ? saved : item);
          if (list.isConnected) displayProjects();
        })));
    }
    filter.addEventListener('change', () => {
      try {
        sessionStorage.setItem('project-filter', filter.value);
      } catch { /* Filtering does not depend on storage availability. */ }
      displayProjects();
    });
    // Wait for the initial list before allowing creation, keeping creation order stable.
    submit.disabled = true;
    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      if (submit.disabled) return;
      const name = input.value.trim();
      if (!name) {
        alertMessage('Project name is required');
        input.focus();
        return;
      }
      submit.disabled = true;
      alertMessage('');
      try {
        const project = await request('/api/projects', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name }),
        });
        projects.push(project);
        if (!form.isConnected) return;
        displayProjects();
        input.value = '';
        input.focus();
      } catch (error) {
        if (form.isConnected) alertMessage(error.message);
      } finally {
        submit.disabled = false;
      }
    });
    try {
      projects = await request('/api/projects');
      if (!list.isConnected) return;
      displayProjects();
    } catch (error) {
      if (list.isConnected) alertMessage(error.message);
    } finally {
      submit.disabled = false;
    }
  }
  if (location.pathname === path) app.setAttribute('aria-busy', 'false');
}

window.addEventListener('popstate', render);
render();
